<!-- Props: shareUrl?, id?, compact?, onToast?, buttonLabel?, dialogHeading?, dialogDescription?, dialogTitleId?, shareTitle?, shareText?, buttonAriaLabel?, urlFieldAriaLabel?, tone?, density?; Emits: —; Slots: —; Exposed: — -->
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { Share2 } from 'lucide-vue-next'
import { appUrl } from '$lib/appUrl'
import { copyTextToClipboard } from '$lib/copy_to_clipboard'
const props=withDefaults(defineProps<{shareUrl?:string;id?:string;compact?:boolean;onToast?:((message:string)=>void)|null;buttonLabel?:string;dialogHeading?:string;dialogDescription?:string;dialogTitleId?:string;shareTitle?:string;shareText?:string;buttonAriaLabel?:string;urlFieldAriaLabel?:string;tone?:'violet'|'cyan';density?:'comfortable'|'sm'}>(),{compact:false,onToast:null,buttonLabel:'Partager',dialogHeading:'Partager la Geobattle',dialogDescription:'Envoie le lien — sur mobile, le menu système regroupe souvent toutes les apps.',dialogTitleId:'geobattle-share-title',shareTitle:'Geobattle — GeoPinpoint',shareText:'Trouve le lieu le plus vite possible sur la carte !',buttonAriaLabel:'Partager cette Geobattle',urlFieldAriaLabel:'URL de la Geobattle',tone:'violet',density:'comfortable'})
const url=computed(()=>props.shareUrl?.trim()||(props.id?appUrl(`/geobattle/${props.id}`):''))
const hasNativeShare=typeof navigator!=="undefined"&&typeof navigator.share==="function"
const busy=ref(false), sheetOpen=ref(false), feedback=ref<string|null>(null), dialog=ref<HTMLElement>(), urlField=ref<HTMLInputElement>()
let feedbackTimer:ReturnType<typeof setTimeout>|undefined
function clearTimer(){if(feedbackTimer)clearTimeout(feedbackTimer)}
function close(){sheetOpen.value=false;feedback.value=null;clearTimer()}
function keydown(e:KeyboardEvent){if(e.key==='Escape'&&sheetOpen.value)close()}
watch(sheetOpen,value=>{if(value){document.addEventListener('keydown',keydown);document.body.style.overflow='hidden';requestAnimationFrame(()=>dialog.value?.focus())}else{document.removeEventListener('keydown',keydown);document.body.style.overflow=''}})
onBeforeUnmount(()=>{clearTimer();document.removeEventListener('keydown',keydown);document.body.style.overflow=''})
function payload(){return{url:url.value.trim(),title:props.shareTitle,text:props.shareText}}
function openSheet(){sheetOpen.value=true}
async function share(){if(busy.value||!url.value.trim())return;const data=payload();if(typeof navigator.share==='function'){const shareData:ShareData={...data};if(typeof navigator.canShare!=='function'||navigator.canShare(shareData)){busy.value=true;try{await navigator.share(shareData)}catch(e){if((e as Error).name!=='AbortError')openSheet()}finally{busy.value=false}return}}openSheet()}
async function copy(){const ok=await copyTextToClipboard(payload().url);feedback.value=ok?'Lien copié.':'Copie automatique impossible : sélectionne le champ ci-dessous, puis « Copier » du clavier.';if(ok)props.onToast?.('Lien copié');clearTimer();feedbackTimer=setTimeout(()=>feedback.value=null,6000)}
const targets=computed(()=>{const {url:u,title,text}=payload(),line=`${text}\n${u}`;return[['WhatsApp',`https://wa.me/?text=${encodeURIComponent(line)}`],['Telegram',`https://t.me/share/url?url=${encodeURIComponent(u)}&text=${encodeURIComponent(text)}`],['Facebook',`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(u)}`],['X (Twitter)',`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(u)}`],['LinkedIn',`https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(u)}`],['E-mail',`mailto:?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(line)}`]] as [string,string][]})
function openExternal(href:string){window.open(href,'_blank','noopener,noreferrer')}
</script>
<template>
<div class="share-trigger"><button type="button" class="btn" :class="[compact?'share-compact':tone==='cyan'?'btn-primary':'btn-secondary',density==='sm'?'btn-sm':'']" :disabled="busy||!url.trim()" :aria-label="buttonAriaLabel" :aria-expanded="sheetOpen" :title="buttonLabel" @click="share"><Share2 :size="compact||density==='sm'?16:20"/><span v-if="!compact">{{buttonLabel}}</span></button></div>
<Teleport to="body"><div v-if="sheetOpen" class="modal-backdrop share-backdrop" role="presentation" @click.self="close"><section ref="dialog" class="modal sm" role="dialog" aria-modal="true" :aria-labelledby="dialogTitleId" tabindex="-1" @keydown.esc.stop="close"><header class="modal-header"><div><h2 :id="dialogTitleId">{{dialogHeading}}</h2><p class="subtle">{{dialogDescription}}</p></div><button type="button" class="btn btn-ghost btn-sm" aria-label="Fermer la boîte de partage" @click="close">Fermer</button></header><div class="modal-body share-body"><div class="share-targets"><template v-for="[label,href] in targets" :key="label"><a v-if="label==='E-mail'" class="btn btn-secondary" :href="href">{{label}}</a><button v-else type="button" class="btn btn-secondary" @click="openExternal(href)">{{label}}</button></template></div><button type="button" class="btn btn-primary btn-block" @click="copy">Copier le lien</button><p v-if="feedback" class="subtle" role="status">{{feedback}}</p><label class="field"><span>Ou sélectionne puis copie depuis le clavier</span><input ref="urlField" type="text" readonly :value="url.trim()" :aria-label="urlFieldAriaLabel" @focus="($event.target as HTMLInputElement).select()" @click="($event.target as HTMLInputElement).select()"/></label><button v-if="hasNativeShare" type="button" class="btn btn-secondary btn-block" @click="close();share()">Menu partage du téléphone…</button></div></section></div></Teleport>
</template>
<style scoped>.share-trigger{display:flex;align-items:center}.share-compact{width:40px;height:40px;padding:0;background:var(--primary-soft);color:var(--primary-strong);border-color:var(--border)}.share-backdrop{z-index:11000}.share-body{display:grid;gap:12px}.share-targets{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.share-targets .btn{padding:7px 8px;white-space:normal}.share-body .field span{font-size:11px;color:var(--muted)}.share-body input{font-family:ui-monospace,monospace;font-size:12px}@media(min-width:600px){.share-targets{grid-template-columns:repeat(3,minmax(0,1fr))}}</style>
